let activeLanguage='en';
try{const requested=new URLSearchParams(location.search).get('lang');activeLanguage=requested==='en'?'en':requested==='zh'?'zh':localStorage.getItem('popomo-language')==='zh'?'zh':'en';}catch{}
const originalText=new WeakMap(),originalAttributes=new WeakMap();
function translateString(value){const trimmed=value.trim();if(translations[trimmed])return value.replace(trimmed,translations[trimmed]);if(/^\d+ 款精选$/.test(trimmed))return value.replace(trimmed,trimmed.split(' ')[0]+' curated designs');if(trimmed.startsWith('预览')&&translations[trimmed.slice(2)])return 'Preview '+translations[trimmed.slice(2)];return value;}
function translateTree(root){const walk=document.createTreeWalker(root,NodeFilter.SHOW_TEXT);const nodes=[];while(walk.nextNode())nodes.push(walk.currentNode);for(const node of nodes){if(node.parentElement.closest('script,style,h1,select,[data-hero-flow]'))continue;let original=originalText.get(node);if(!original||node.nodeValue!==original.last){original={source:node.nodeValue,last:node.nodeValue};originalText.set(node,original);}const next=activeLanguage==='en'?translateString(original.source):original.source;original.last=next;if(node.nodeValue!==next)node.nodeValue=next;}
 root.querySelectorAll('[aria-label],img[alt]').forEach(el=>{let originals=originalAttributes.get(el);if(!originals){originals={};originalAttributes.set(el,originals);}for(const attr of ['aria-label','alt']){if(!el.hasAttribute(attr)||el.id==='language-select'||el.closest('[data-hero-flow]'))continue;if(!(attr in originals))originals[attr]=el.getAttribute(attr);el.setAttribute(attr,activeLanguage==='en'?translateString(originals[attr]):originals[attr]);}});
}
const headlineZh=document.querySelector('h1').innerHTML;
const titleMark='<svg viewBox="0 0 260 20" aria-hidden="true"><path d="M4 12Q126 0 254 10M18 18Q127 9 239 16"/></svg>';
function setLanguage(lang,initial=false){activeLanguage=lang;document.documentElement.lang=lang==='en'?'en':'zh-CN';document.documentElement.dataset.language=lang;document.querySelector('#language-select').value=lang;const h=document.querySelector('h1');h.innerHTML=lang==='en'?`<span class="scroll-title-line">A little <span class="v2-orange">imagination.</span></span><span class="scroll-title-line">A case like <span class="v2-inline">no other.</span></span>`:headlineZh;h.setAttribute('aria-label',lang==='en'?'A little imagination. A case like no other.':'把你的奇思妙想，变成手心的独一无二。');if(!initial&&!matchMedia('(prefers-reduced-motion: reduce)').matches)h.animate([{opacity:.25,transform:'translateY(5px)'},{opacity:1,transform:'translateY(0)'}],{duration:250});translateTree(document.body);document.title=lang==='en'?'POPOMO — Keep what you love close.':'POPOMO — 把喜欢，带在身边。';try{localStorage.setItem('popomo-language',lang);if(!initial){const url=new URL(location.href);url.searchParams.set('lang',lang);history.replaceState(null,'',url);}}catch{}}
setLanguage(activeLanguage,true);
document.querySelector('#language-select').addEventListener('change',e=>setLanguage(e.target.value));
const languageObserver=new MutationObserver(()=>{languageObserver.disconnect();translateTree(document.body);languageObserver.observe(document.body,{childList:true,subtree:true,characterData:true});});
languageObserver.observe(document.body,{childList:true,subtree:true,characterData:true});
